suppressPackageStartupMessages({library(dplyr); library(tidyr); library(readr); library(stringr); library(purrr); library(tibble); library(ggplot2); library(forcats); library(splines)})
for (f in sort(list.files("R", pattern = "^[0-9].*\\.R$", full.names = TRUE))) source(f)
TM <- readRDS("data/processed/team_match.rds"); VF <- readRDS("data/processed/value_frame.rds"); M <- readRDS("data/processed/match.rds")
V <- readRDS("outputs/models/value.rds"); AU <- readRDS("data/processed/auction.rds"); WPA <- readRDS("data/processed/wpa.rds")
D <- readRDS("data/processed/deliveries_feat.rds"); PR <- readRDS("data/processed/player_prices.rds"); PS <- readRDS("data/processed/player_season.rds")
SCR <- run_team_screen(TM, VF, V, WPA); saveRDS(SCR, "outputs/models/team_screen.rds"); TEAM <- SCR$team
X <- run_diagnosis(VF, WPA, D, TEAM, HOME_GROUND[[TEAM]], V$pv$shrink$bowl$k, V$pv$shrink$bat$k)
saveRDS(c(X, team = TEAM), "outputs/models/diagnosis.rds")
A <- run_decision_audit(SCR, VF, V, AU, TM, M, TEAM); saveRDS(A, "outputs/models/decision_audit.rds")
O <- build_options(VF, V, PR, AU, X, PS, TEAM); RV <- retention_view(V, TEAM); EV <- team_evidence(SCR, X, A, O, TEAM)
saveRDS(list(options = O[setdiff(names(O), "sims")], sims = O$sims, retention = RV, evidence = EV), "outputs/models/recommend.rds")
options(width=220); print(as.data.frame(RV |> select(player, role_sheet, price_cr, war_total, war_2yr, surplus_cr, call)))
for(i in 1:8) cat(EV$id[i], EV$evidence[i], "\n")
print(O$sim_sum); print(head(O$shortlist |> select(player, main_team, balls, shrunk_per100, price_cr, proj_wins), 8))
